ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_EksportWydruki]
	@RowVersion BIGINT,
	@PointOfSaleId INT
AS
BEGIN
SET NOCOUNT ON;
	select
		isnull((select max(Pwr_CzasModyfikacji) from cdn.picostanowiskawydruki where pwr_psaid = @PointOfSaleId AND (Pwr_CzasModyfikacji > @RowVersion OR @RowVersion = 0)),0) as [@RowVersion], (
		select
			pwr_nazwaPos as [@InternalName],
			pwr_nazwa as [@Name],
			pwr_kopie as [@NumberOfCopies],
			'true' as [@IsActive]
		from cdn.picostanowiskawydruki
		where pwr_psaid = @PointOfSaleId AND (Pwr_CzasModyfikacji > @RowVersion OR @RowVersion = 0) AND PWr_Wysylaj = 1
	for xml path('Printout'), type)
	for xml path('Printouts')
	SET NOCOUNT OFF;	
END
